import { CommonModule } from '@angular/common';
import { HttpClient } from '@angular/common/http';
import { Component, inject } from '@angular/core';
import { FormsModule } from '@angular/forms';
import { GiftCardAdminComponent } from './gift-card-admin.component';
type Product={id:string;name:string;description:string;sku:string;active:boolean;variants?:Array<{id:string;name:string}>};
@Component({selector:'artio-admin',standalone:true,imports:[CommonModule,FormsModule,GiftCardAdminComponent],template:`
<div *ngIf="!token && !setupChecked" class="login-page"><div class="login-card"><a class="brand">artio<span> / studio</span></a><p class="muted">Checking store setup…</p></div></div>
<div *ngIf="!token && setupChecked && setupRequired" class="login-page"><div class="login-card setup-card"><a class="brand">artio<span> / setup</span></a><p class="eyebrow">FIRST-RUN SETUP <span *ngIf="developerMode" class="badge">Developer mode</span></p><h1>Set up your store.</h1><p class="muted">Switzerland distribution · CHF · de-CH · Europe/Zurich. This secure, resumable wizard stores progress without passwords or integration secrets. Stripe and Swiss Post can be installed disabled after setup.</p><form (ngSubmit)="saveSetupProgress()"><label>One-time setup token<input [(ngModel)]="setupToken" name="setupToken" type="password" autocomplete="off" required></label><label>Store name<input [(ngModel)]="setupDraft.storeName" name="storeName" maxlength="120" required></label><div class="form-grid"><label>Country code<input [(ngModel)]="setupDraft.countryCode" name="countryCode" maxlength="2" placeholder="CH" required></label><label>Currency<input [(ngModel)]="setupDraft.currencyCode" name="currencyCode" maxlength="3" placeholder="CHF" required></label></div><div class="form-grid"><label>Default locale<input [(ngModel)]="setupDraft.locale" name="locale" placeholder="de-CH" required></label><label>Time zone<input [(ngModel)]="setupDraft.timezone" name="timezone" placeholder="Europe/Zurich" required></label></div><label>Available languages<input [(ngModel)]="setupDraft.availableLanguages" name="availableLanguages" placeholder="de,fr,it,en" required><small>Comma-separated BCP 47 language tags.</small></label><label>External store URL<input [(ngModel)]="setupDraft.externalBaseUrl" name="externalBaseUrl" type="url" placeholder="https://shop.example.com"><small>HTTPS is required for public URLs.</small></label><label>Administrator email<input [(ngModel)]="setupDraft.email" name="setupEmail" type="email" required></label><div class="form-grid"><label>First name<input [(ngModel)]="setupDraft.firstName" name="setupFirstName" required></label><label>Last name<input [(ngModel)]="setupDraft.lastName" name="setupLastName" required></label></div><label>Administrator password<input [(ngModel)]="setupPassword" name="setupPassword" type="password" minlength="16" maxlength="72" autocomplete="new-password" required><small>Use 16–72 characters. Password is sent only when completing setup.</small></label><button class="primary" [disabled]="setupBusy">{{setupBusy?'Saving…':'Save and complete setup'}} <span>↗</span></button></form><p class="error" *ngIf="error">{{error}}</p><p class="muted">Your setup token stays in this browser session and is never stored by the wizard.</p></div></div>
<div *ngIf="!token && setupChecked && !setupRequired" class="login-page"><div class="login-card"><a class="brand">artio<span> / studio</span></a><p class="eyebrow">Commerce, thoughtfully run</p><h1>Welcome back.</h1><p class="muted">Sign in to manage your Artio store.</p><form (ngSubmit)="login()"><label>Email<input [(ngModel)]="email" name="email" type="email" required></label><label>Password<input [(ngModel)]="password" name="password" type="password" required></label><button class="primary">Sign in <span>↗</span></button></form><p class="error" *ngIf="error">{{error}}</p></div></div>
<div *ngIf="token" class="shell"><a class="skip-link" href="#main-content">Skip to main content</a><aside class="sidebar"><a class="brand">artio<span> / studio</span></a><p class="label">WORKSPACE</p><button [class.selected]="tab==='overview'" (click)="tab='overview'">◫ &nbsp; Overview</button><button [class.selected]="tab==='products'" (click)="tab='products';loadProducts()">▦ &nbsp; Products</button><button [class.selected]="tab==='bundles'" (click)="tab='bundles';loadBundles()">✳ &nbsp; Bundles</button><button [class.selected]="tab==='extensions'" (click)="tab='extensions';loadExtensions()">⬡ &nbsp; Extensions</button><button [class.selected]="tab==='pricing'" (click)="tab='pricing';loadPrices()">◉ &nbsp; Pricing</button><button [class.selected]="tab==='inventory'" (click)="tab='inventory'">▤ &nbsp; Inventory</button><button [class.selected]="tab==='orders'" (click)="tab='orders';loadOrders()">↗ &nbsp; Orders</button><button [class.selected]="tab==='users'" (click)="tab='users';loadUsers()">♙ &nbsp; Customers</button><button [class.selected]="tab==='giftCards'" (click)="tab='giftCards'">▣ &nbsp; Gift cards</button><button [class.selected]="tab==='operations'" (click)="tab='operations';loadOutbox()">▣ &nbsp; Operations</button><button *ngIf="isSuperadmin" [class.selected]="tab==='system'" (click)="tab='system';loadSystemSettings()">⚙ &nbsp; System Settings</button><div class="sidebar-bottom"><span class="avatar">{{email.charAt(0).toUpperCase()}}</span><div><strong>{{email}}</strong><small>Administrator</small></div><button class="logout" (click)="logout()">↪</button></div></aside>
<main class="content" id="main-content" tabindex="-1"><header><div><p class="eyebrow">TUESDAY, OCTOBER 13</p><h1>{{ title }}</h1></div><div class="header-actions"><a href="http://localhost:4200" target="_blank">View storefront ↗</a><span class="status"><i></i> Store online</span></div></header>
<section *ngIf="tab==='overview'"><div class="welcome"><div><p class="eyebrow">YOUR STORE AT A GLANCE</p><h2>Good morning.</h2><p>A calm view of what’s happening across your store today.</p></div><div class="welcome-mark">✳</div></div><div class="metrics"><article><span>Active products</span><strong>{{products.length}}</strong><small>Across your catalogue</small></article><article><span>Active bundles</span><strong>{{bundles.length}}</strong><small>Ready to configure</small></article><article><span>Orders</span><strong>{{orders.length}}</strong><small>Recent orders</small></article><article><span>Price entries</span><strong>{{prices.length}}</strong><small>Markets & channels</small></article></div><div class="panel"><div class="panel-heading"><div><p class="eyebrow">RECENT ACTIVITY</p><h2>Products in your catalogue</h2></div><button class="link-button" (click)="tab='products'">View all →</button></div><div class="row" *ngFor="let product of products.slice(0,5)"><span class="dot-icon">{{product.name.charAt(0)}}</span><div class="row-main"><strong>{{product.name}}</strong><small>{{product.sku}}</small></div><span class="pill" [class.inactive]="!product.active">{{product.active?'Active':'Inactive'}}</span></div><p *ngIf="!products.length" class="empty">Your catalogue is ready for its first product.</p></div></section>
<section *ngIf="tab==='products'"><div class="toolbar"><label class="search">⌕ <input [(ngModel)]="query" placeholder="Search products"></label><button class="link-button" (click)="rebuildSearchIndex()">Rebuild search index</button><button class="primary" (click)="showCreate=!showCreate">＋ New product</button></div><p class="muted" *ngIf="searchIndexStatus">{{searchIndexStatus}}</p><form *ngIf="showCreate" class="create-form" (ngSubmit)="createProduct()"><input [(ngModel)]="draft.name" name="name" placeholder="Product name" required><input [(ngModel)]="draft.sku" name="sku" placeholder="SKU" required><input [(ngModel)]="draft.description" name="description" placeholder="Description"><button class="primary">Save product</button></form><div class="panel table-panel"><table><thead><tr><th>PRODUCT</th><th>SKU / VARIANT ID</th><th>STATUS</th><th>ACTION</th></tr></thead><tbody><tr *ngFor="let product of filteredProducts"><td><strong>{{product.name}}</strong><small>{{product.description}}</small></td><td>{{product.sku}}<small *ngFor="let variant of product.variants">{{variant.name}} · {{variant.id}}</small></td><td><span class="pill" [class.inactive]="!product.active">{{product.active?'Active':'Inactive'}}</span></td><td><button class="link-button" (click)="toggle(product)">{{product.active?'Deactivate':'Activate'}}</button><button class="link-button" (click)="editTranslations(product)">Translations</button></td></tr></tbody></table><p *ngIf="!filteredProducts.length" class="empty">No products found.</p></div><div *ngIf="translationProduct" class="panel"><div class="panel-heading"><div><p class="eyebrow">LOCALIZED CATALOG</p><h2>{{translationProduct.name}}</h2></div><button class="link-button" (click)="translationProduct=null">Close</button></div><form class="create-form" (ngSubmit)="saveTranslation()"><select [(ngModel)]="translationLocale" name="translationLocale" (ngModelChange)="loadTranslation()"><option value="de">German · de</option><option value="it">Italian · it</option><option value="fr">French · fr</option><option value="en">English · en</option></select><input [(ngModel)]="translationDraft.name" name="localizedName" placeholder="Translated product name" required><textarea [(ngModel)]="translationDraft.description" name="localizedDescription" placeholder="Translated description" rows="3"></textarea><button class="primary">Save translation</button></form></div></section>
<section *ngIf="tab==='bundles'"><div class="toolbar"><p>Curate fixed sets or configurable bundles with live quotes.</p><button class="primary" (click)="showBundle=!showBundle">＋ New bundle</button></div><form *ngIf="showBundle" class="create-form" (ngSubmit)="createBundle()"><input [(ngModel)]="bundleDraft.name" name="bundleName" placeholder="Bundle name" required><input [(ngModel)]="bundleDraft.sku" name="bundleSku" placeholder="Bundle SKU" required><select [(ngModel)]="bundleDraft.type" name="bundleType"><option value="CONFIGURABLE">Configurable</option><option value="FIXED">Fixed</option></select><input [(ngModel)]="bundleDraft.sellables" name="sellables" placeholder="Variant UUIDs, comma separated" required><button class="primary">Create bundle</button></form><div class="bundle-list"><article *ngFor="let b of bundles"><div class="bundle-mark">✳</div><p class="eyebrow">{{b.type}}</p><h2>{{b.name}}</h2><span class="pill" [class.inactive]="!b.active">{{b.active?'Active':'Inactive'}}</span><button class="link-button" (click)="activateBundle(b)">{{b.active?'Deactivate':'Activate'}}</button><button class="link-button" (click)="editBundleTranslation(b)">Translations</button></article></div><div *ngIf="bundleTranslationBundle" class="panel"><div class="panel-heading"><div><p class="eyebrow">LOCALIZED CONFIGURATOR</p><h2>{{bundleTranslationBundle.name}}</h2></div><button class="link-button" (click)="bundleTranslationBundle=null">Close</button></div><form class="create-form" (ngSubmit)="saveBundleTranslation()"><select [(ngModel)]="bundleTranslationLocale" name="bundleTranslationLocale" (ngModelChange)="loadBundleTranslation()"><option value="de">German · de</option><option value="it">Italian · it</option><option value="fr">French · fr</option><option value="en">English · en</option></select><input [(ngModel)]="bundleTranslationDraft.name" name="localizedBundleName" placeholder="Translated bundle name" required><label *ngFor="let group of bundleTranslationBundle.optionGroups">{{group.name}}<input [(ngModel)]="bundleTranslationDraft.optionGroupNames[group.code]" [name]="'bundle-translation-'+group.code" placeholder="Translated option-group label" required></label><button class="primary">Save translations</button></form></div></section>
<section *ngIf="tab==='extensions'"><div class="toolbar"><p>Register trusted extensions and manage schema-defined settings.</p><button class="primary" (click)="showExtensionRegistration=!showExtensionRegistration">＋ Register extension</button></div><p class="error" *ngIf="error">{{error}}</p><p class="muted" *ngIf="extensionHealth">{{extensionHealth}}</p><form *ngIf="showExtensionRegistration" class="create-form" (ngSubmit)="registerExtension()"><textarea [(ngModel)]="extensionManifestJson" name="extensionManifest" rows="10" placeholder="Paste extension manifest JSON" required></textarea><button class="primary">Validate and register</button></form><div class="bundle-list"><article *ngFor="let extension of extensions"><div class="bundle-mark">⬡</div><p class="eyebrow">{{extension.id}}</p><h2>{{extension.name}}</h2><span class="pill">{{extension.lifecycleState}}</span><small>v{{extension.version}} · {{extension.configuredSecrets.length}} configured secret(s)</small><small>Availability: {{extension.geographicAvailability?.scope || 'GLOBAL'}}{{extension.geographicAvailability?.countries?.length ? ' · ' + extension.geographicAvailability.countries.join(', ') : ''}}</small><button *ngIf="extension.lifecycleState==='CONFIGURED' || extension.lifecycleState==='FAILED'" class="link-button" (click)="extensionAction(extension,'install')">Install</button><button *ngIf="extension.lifecycleState==='INSTALLED' || extension.lifecycleState==='DISABLED'" class="link-button" (click)="extensionAction(extension,'enable')">Enable</button><button *ngIf="extension.lifecycleState==='ENABLED'" class="link-button" (click)="extensionAction(extension,'disable')">Disable</button><button *ngIf="extension.lifecycleState==='ENABLED' || extension.lifecycleState==='DISABLED' || extension.lifecycleState==='INSTALLED'" class="link-button" (click)="rotateExtensionCredentials(extension)">Rotate credential</button><button *ngIf="extension.lifecycleState==='INSTALLED' || extension.lifecycleState==='DISABLED'" class="link-button" (click)="updateExtension(extension)">Update</button><button *ngIf="extension.lifecycleState==='INSTALLED' || extension.lifecycleState==='DISABLED'" class="link-button" (click)="rollbackExtension(extension)">Rollback</button><button class="link-button" (click)="checkExtensionHealth(extension)">Health</button><button *ngIf="extension.id==='observability.artio' && extension.lifecycleState==='ENABLED'" class="link-button" (click)="openObservability()">Open dashboards</button><button class="link-button" (click)="selectExtension(extension)">Configure</button><button class="link-button" (click)="loadExtensionAudit(extension)">Activity</button><button *ngIf="extension.lifecycleState!=='UNINSTALLED'" class="link-button danger" (click)="uninstallExtension(extension)">Uninstall</button></article></div><div *ngIf="extensionAuditFor" class="panel table-panel"><div class="panel-heading"><div><p class="eyebrow">EXTENSION ACTIVITY</p><h2>{{extensionAuditFor}}</h2></div><button class="link-button" (click)="extensionAuditFor=null;extensionAudit=[]">Close</button></div><p class="muted">Recent administrative lifecycle and invocation events. Secret values and request bodies are excluded.</p><table><thead><tr><th>TIME</th><th>ACTOR</th><th>ACTION</th><th>DETAILS</th></tr></thead><tbody><tr *ngFor="let event of extensionAudit"><td>{{event.occurredAt | date:"medium"}}</td><td>{{event.actorUserId}}</td><td>{{event.action}}</td><td>{{event.details | json}}</td></tr></tbody></table><p *ngIf="extensionAudit.length===0" class="empty">No activity recorded.</p></div><div *ngIf="selectedExtension?.lifecycleState==='ENABLED'" class="panel"><p class="eyebrow">LIVE DIAGNOSTIC</p><h2>Invoke extension</h2><p class="muted">This sends a real request to the enabled extension. Use a non-destructive operation and sample payload.</p><form class="create-form" (ngSubmit)="invokeExtension()"><select [(ngModel)]="extensionInvocation.extensionPoint" name="extensionPoint" required><option *ngFor="let point of selectedExtension.manifest.extensionPoints" [value]="point">{{point}}</option></select><input [(ngModel)]="extensionInvocation.operation" name="operation" placeholder="Operation" required><textarea [(ngModel)]="extensionInvocation.payloadJson" name="payload" rows="5" required></textarea><button class="primary">Send diagnostic request</button></form><pre *ngIf="extensionInvocationResult">{{extensionInvocationResult | json}}</pre></div><div *ngIf="selectedExtension" class="panel"><div class="panel-heading"><div><p class="eyebrow">EXTENSION SETTINGS</p><h2>{{selectedExtension.manifest.name}}</h2></div><button class="link-button" (click)="selectedExtension=null">Close</button></div><form class="create-form" (ngSubmit)="saveExtensionConfiguration()"><ng-container *ngFor="let field of extensionFields()"><div class="create-field"><span>{{field.value.label || field.key}}</span><small *ngIf="field.value.description">{{field.value.description}}</small><select *ngIf="field.value.type==='enum'" [(ngModel)]="extensionConfig[field.key]" [name]="'extension-'+field.key"><option *ngFor="let option of field.value.options" [value]="option">{{option}}</option></select><input *ngIf="field.value.type==='secret'" type="password" autocomplete="new-password" [(ngModel)]="extensionConfig[field.key]" [name]="'extension-'+field.key" [placeholder]="selectedExtension.configuredSecrets.includes(field.key) ? 'Configured — leave blank to keep existing value' : 'Secret value'" [required]="field.value.required && !selectedExtension.configuredSecrets.includes(field.key)"><input *ngIf="field.value.type==='text' || field.value.type==='number' || field.value.type==='url'" [type]="field.value.type==='number'?'number':'text'" [(ngModel)]="extensionConfig[field.key]" [name]="'extension-'+field.key" [required]="field.value.required"><textarea *ngIf="field.value.type==='json'" [(ngModel)]="extensionConfig[field.key]" [name]="'extension-'+field.key" rows="4" [required]="field.value.required"></textarea><label *ngIf="field.value.type==='boolean'"><input type="checkbox" [(ngModel)]="extensionConfig[field.key]" [name]="'extension-'+field.key"> Enabled</label></div></ng-container><button class="primary">Save configuration</button></form></div></section>
<section *ngIf="tab==='system'"><div class="panel"><p class="eyebrow">SYSTEM SETTINGS</p><h2>Installation configuration</h2><p class="muted">Changes are restricted to the system owner and recorded in the audit history.</p><form class="create-form" (ngSubmit)="saveSystemSettings()"><label>Store name<input [(ngModel)]="systemSettings.storeName" name="storeName" maxlength="120" required></label><div class="form-grid"><label>Country<input [(ngModel)]="systemSettings.countryCode" name="countryCode" maxlength="2" required></label><label>Currency<input [(ngModel)]="systemSettings.currencyCode" name="currencyCode" maxlength="3" required></label></div><div class="form-grid"><label>Default locale<input [(ngModel)]="systemSettings.locale" name="locale" required></label><label>Time zone<input [(ngModel)]="systemSettings.timezone" name="timezone" required></label></div><label>Supported languages<input [(ngModel)]="systemLanguages" name="languages" placeholder="de, fr, it, en" required><small>Comma-separated BCP 47 language tags.</small></label><label>External store URL<input [(ngModel)]="systemSettings.externalBaseUrl" name="externalBaseUrl" type="url" placeholder="https://shop.example.com"><small>HTTPS is required outside local development.</small></label><p class="muted">Distribution: {{systemSettings.distributionId}}</p><button class="primary">Save installation settings</button></form><button class="link-button" (click)="tab='extensions';loadExtensions()">Open Plugin Manager</button></div><div class="panel table-panel"><p class="eyebrow">REGIONAL PLUGIN PROVISIONING</p><h2>Recommended integrations</h2><p class="muted">Optional plugins are installed disabled. Enable them only after reviewing their settings. Missing releases stay unavailable until a trusted digest-pinned manifest is registered.</p><table><thead><tr><th>PLUGIN</th><th>STATUS</th><th>RECOMMENDATION</th></tr></thead><tbody><tr *ngFor="let item of distributionPlugins"><td>{{item.pluginId}}</td><td>{{item.status}}</td><td>{{item.reason}}</td></tr></tbody></table><p *ngIf="!distributionPlugins.length" class="empty">No regional plugin recommendations are configured.</p><button class="link-button" (click)="refreshDistributionPlugins()">Refresh provisioning status</button></div><div class="panel table-panel"><p class="eyebrow">SYSTEM SETTINGS AUDIT</p><h2>Recent changes</h2><table><thead><tr><th>TIME</th><th>ACTOR</th><th>METHOD</th><th>STATUS</th></tr></thead><tbody><tr *ngFor="let event of systemSettingsAudit"><td>{{event.occurredAt | date:"medium"}}</td><td>{{event.userId}}</td><td>{{event.action}} {{event.path}}</td><td>{{event.status}}</td></tr></tbody></table><p *ngIf="!systemSettingsAudit.length" class="empty">No settings changes recorded.</p></div></section><section *ngIf="tab==='pricing'"><div class="toolbar"><p>Manage selling prices by market and channel.</p><button class="primary" (click)="showPrice=!showPrice">＋ Add price</button></div><form *ngIf="showPrice" class="create-form" (ngSubmit)="createPrice()"><input [(ngModel)]="priceDraft.sellableId" name="sellable" placeholder="Product or variant UUID" required><input [(ngModel)]="priceDraft.amount" name="amount" type="number" placeholder="Amount" required><input [(ngModel)]="priceDraft.currency" name="currency" placeholder="USD" required><input [(ngModel)]="priceDraft.market" name="market" placeholder="US" required><input [(ngModel)]="priceDraft.channel" name="channel" placeholder="WEB" required><label><input type="checkbox" [(ngModel)]="priceDraft.pricesIncludeTax" name="pricesIncludeTax"> Price includes tax</label><button class="primary">Save price</button></form><div class="panel table-panel"><table><thead><tr><th>SELLABLE</th><th>MARKET / CHANNEL</th><th>PRICE</th><th>TAX MODE</th><th>STATUS</th></tr></thead><tbody><tr *ngFor="let p of prices"><td>{{p.sellableId}}</td><td>{{p.market}} / {{p.channel}}</td><td>{{p.amount}} {{p.currency}}</td><td>{{p.pricesIncludeTax?'Tax inclusive':'Tax exclusive'}}</td><td>{{p.active?'Active':'Inactive'}}</td></tr></tbody></table></div></section>
<section *ngIf="tab==='pricing'"><div class="panel"><div class="panel-heading"><div><p class="eyebrow">TAX POLICY</p><h2>Sellable tax categories</h2></div></div><p class="muted">Assign categories using your merchant tax policy. Classification is not inferred from product text.</p><form class="create-form" (ngSubmit)="assignTaxCategory()"><input [(ngModel)]="taxAssignment.sellableId" name="taxSellableId" placeholder="Product or variant UUID" required><select [(ngModel)]="taxAssignment.category" name="taxCategory"><option value="STANDARD">Standard</option><option value="REDUCED">Reduced</option><option value="ACCOMMODATION">Accommodation</option></select><button class="primary">Assign category</button></form><div class="table-panel" *ngIf="taxRules.length"><table><thead><tr><th>JURISDICTION</th><th>CATEGORY</th><th>RATE</th><th>VALID FROM</th><th>STATUS</th></tr></thead><tbody><tr *ngFor="let rule of taxRules"><td>{{rule.jurisdiction}}</td><td>{{rule.category}}</td><td>{{rule.percentage}}%</td><td>{{rule.validFrom}}</td><td>{{rule.active?'Active':'Inactive'}}</td></tr></tbody></table></div><div class="table-panel" *ngIf="sellableTaxCategories.length"><table><thead><tr><th>SELLABLE ID</th><th>ASSIGNED CATEGORY</th></tr></thead><tbody><tr *ngFor="let assignment of sellableTaxCategories"><td>{{assignment.sellableId}}</td><td>{{assignment.category}}</td></tr></tbody></table></div></div></section>
<section *ngIf="tab==='inventory' || tab==='orders'"><div class="panel"><p class="eyebrow">{{tab==='inventory'?'STOCK OPERATIONS':'FULFILMENT'}}</p><h2>{{tab==='inventory'?'Inventory overview':'Orders'}}</h2><p class="muted">{{tab==='inventory'?'Warehouse and stock balances are managed through the inventory API.':'Search, review and fulfil customer orders.'}}</p><form *ngIf="tab==='orders'" class="toolbar" (ngSubmit)="searchOrders()"><input [(ngModel)]="ordersQuery" name="orderQuery" maxlength="200" placeholder="Order ID, customer email or tracking"><select [(ngModel)]="ordersStatus" name="orderStatus"><option value="">All statuses</option><option *ngFor="let status of orderStatuses" [value]="status">{{status}}</option></select><button class="primary">Search</button><button type="button" class="link-button" (click)="exportOrders()">Export CSV</button></form><p class="muted" *ngIf="tab==='orders'">{{orderTotal}} orders · page {{orderPage+1}} of {{orderPages||1}}</p><div *ngFor="let order of orders" class="row"><span class="row-main"><strong>{{order.id}}</strong><small>{{order.status}} · {{order.createdAt | date:'medium'}} · {{order.customerEmail}} {{order.trackingNumber?'· '+order.trackingNumber:''}}</small></span><b>{{order.total}} {{order.currency}}</b><button *ngIf="tab==='orders'" class="link-button" (click)="viewOrder(order)">Details</button><button *ngIf="tab==='orders' && (order.status==='PAID' || order.status==='CONFIRMED')" class="link-button" (click)="shipOrder(order)">{{order.shippingMethodId?'Create label & ship':'Ship'}}</button><button *ngIf="tab==='orders' && order.shippingLabelAvailable" class="link-button" (click)="openShippingLabel(order)">Shipping label ↗</button><button *ngIf="tab==='orders' && order.status==='SHIPPED'" class="link-button" (click)="deliverOrder(order)">Mark delivered</button><button *ngIf="tab==='orders' && order.trackingNumber && order.status==='SHIPPED'" class="link-button" (click)="refreshOrderTracking(order)">Refresh tracking</button></div><p *ngIf="tab==='orders' && !orders.length" class="empty">No orders match these filters.</p><div class="toolbar" *ngIf="tab==='orders'"><button class="link-button" [disabled]="orderPage===0" (click)="loadOrders(orderPage-1)">← Previous</button><button class="link-button" [disabled]="orderPage+1>=orderPages" (click)="loadOrders(orderPage+1)">Next →</button></div><a class="link-button" href="/api/v1/warehouses" target="_blank" *ngIf="tab==='inventory'">Open warehouse API ↗</a></div><div *ngIf="selectedOrder" class="panel"><div class="panel-heading"><div><p class="eyebrow">ORDER DETAIL</p><h2>{{selectedOrder.id}}</h2></div><button class="link-button" (click)="selectedOrder=null">Close</button></div><p><strong>{{selectedOrder.status}}</strong> · {{selectedOrder.customerEmail}} · {{selectedOrder.createdAt | date:'medium'}}</p><p>Subtotal {{selectedOrder.subtotal}} + tax {{selectedOrder.tax}} + shipping {{selectedOrder.shipping}} = <strong>{{selectedOrder.total}} {{selectedOrder.currency}}</strong></p><p>Ship to: {{selectedOrder.shippingAddress}}</p><p>Bill to: {{selectedOrder.billingAddress}}</p><p *ngIf="selectedOrder.trackingNumber">Tracking: {{selectedOrder.trackingNumber}} · {{selectedOrder.shipmentReference}}</p><h3>Items</h3><div class="row" *ngFor="let line of selectedOrder.lines"><span>{{line.variantId}} {{line.bundleId?'· bundle '+line.bundleId:''}} · quantity {{line.quantity}}</span><b>{{line.unitPrice}} {{line.currency}}</b></div><h3>Payments</h3><div class="row" *ngFor="let payment of selectedOrder.payments"><span>{{payment.method}} · {{payment.status}} · {{payment.providerReference}} · refunded {{payment.refundedAmount}} {{payment.currency}}</span><b>{{payment.amount}} {{payment.currency}}</b><button *ngIf="payment.status==='CAPTURED' || payment.status==='PARTIALLY_REFUNDED'" class="link-button" (click)="refundPayment(payment)">Refund</button></div><h3>Returns</h3><div class="row" *ngFor="let item of selectedReturns"><span class="row-main"><strong>{{item.status}}</strong><small>{{item.reason}} · {{item.createdAt | date:'medium'}} · <span *ngFor="let line of item.items">{{line.quantity}} × {{line.orderItemId}} </span></small><small *ngIf="item.staffNote">Staff note: {{item.staffNote}}</small></span><button *ngIf="item.status==='REQUESTED'" class="link-button" (click)="reviewReturn(item,true)">Approve</button><button *ngIf="item.status==='REQUESTED'" class="link-button" (click)="reviewReturn(item,false)">Reject</button><button *ngIf="item.status==='APPROVED'" class="link-button" (click)="receiveReturn(item)">Receive return</button></div><p *ngIf="!selectedReturns.length" class="muted">No return requests for this order.</p><pre>{{selectedOrder.taxSnapshot | json}}</pre><h3>Timeline & staff notes</h3><div class="row" *ngFor="let event of selectedTimeline"><span class="row-main"><strong>{{event.eventType}}</strong><small>{{event.message}} · {{event.occurredAt | date:'medium'}}</small></span><span class="muted">{{event.customerVisible?'Customer visible':'Internal'}}</span></div><form class="toolbar" (ngSubmit)="addOrderNote()"><input [(ngModel)]="orderNote" name="orderNote" maxlength="2000" placeholder="Internal staff note"><button class="primary" [disabled]="!orderNote.trim()">Add note</button></form></div></section>
<artio-gift-card-admin *ngIf="tab==='giftCards'"></artio-gift-card-admin><section *ngIf="tab==='operations'"><div class="panel"><div class="panel-heading"><div><p class="eyebrow">DELIVERY HEALTH</p><h2>Outbox queues</h2></div><button class="link-button" (click)="loadOutbox()">Refresh</button></div><div class="metrics" *ngIf="outboxDiagnostics"><article><span>Pending events</span><strong>{{outboxDiagnostics.eventPending}}</strong><small>{{outboxDiagnostics.eventStaleClaims}} stale claims</small></article><article><span>Dead events</span><strong>{{outboxDiagnostics.eventDead}}</strong><small>Review and replay below</small></article><article><span>Pending email</span><strong>{{outboxDiagnostics.emailPending}}</strong><small>{{outboxDiagnostics.emailStaleClaims}} stale claims</small></article><article><span>Dead email</span><strong>{{outboxDiagnostics.emailDead}}</strong><small>Requires operator review</small></article><article><span>Webhook receipts</span><strong>{{outboxDiagnostics.webhookUnprocessed}}</strong><small>{{outboxDiagnostics.webhookOlderThanRetention}} past retention</small></article></div><div class="panel table-panel" *ngIf="outboxDeadEvents.length"><h3>Dead-letter events</h3><table><thead><tr><th>TYPE</th><th>AGGREGATE</th><th>ATTEMPTS</th><th>ERROR CLASS</th><th>ACTION</th></tr></thead><tbody><tr *ngFor="let event of outboxDeadEvents"><td>{{event.eventType}}</td><td>{{event.aggregateId}}</td><td>{{event.attempts}}</td><td>{{event.errorClass}}</td><td><button class="link-button" (click)="replayOutboxEvent(event)">Replay</button></td></tr></tbody></table></div><div class="panel"><div class="panel-heading"><div><p class="eyebrow">KAFKA</p><h2>Consumer health</h2></div></div><p *ngIf="kafkaConsumerLag">{{kafkaConsumerLag.group}} · {{kafkaConsumerLag.topic}} · {{kafkaConsumerLag.totalLag}} messages behind</p><table *ngIf="kafkaConsumerLag.partitions.length"><thead><tr><th>PARTITION</th><th>COMMITTED</th><th>END</th><th>LAG</th></tr></thead><tbody><tr *ngFor="let partition of kafkaConsumerLag.partitions"><td>{{partition.partition}}</td><td>{{partition.committedOffset}}</td><td>{{partition.endOffset}}</td><td>{{partition.lag}}</td></tr></tbody></table><p *ngIf="!kafkaConsumerLag" class="empty">Consumer lag unavailable; verify Kafka broker and topic.</p><div class="metrics"><article><span>Dead letters</span><strong>{{kafkaDeadLetters.dead}}</strong></article><article><span>Replay pending</span><strong>{{kafkaDeadLetters.replayPending}}</strong></article><article><span>Replayed</span><strong>{{kafkaDeadLetters.replayed}}</strong></article></div><div class="panel table-panel" *ngIf="kafkaDeadLetterItems.length"><h3>Kafka consumer dead letters</h3><table><thead><tr><th>EVENT</th><th>SOURCE</th><th>OFFSET</th><th>FAILURE</th><th>ATTEMPTS</th><th>ACTION</th></tr></thead><tbody><tr *ngFor="let event of kafkaDeadLetterItems"><td>{{event.eventType||event.eventId||'Unknown event'}}</td><td>{{event.sourceTopic}} / {{event.partition}}</td><td>{{event.offset}}</td><td>{{event.errorClass}}</td><td>{{event.replayAttempts}}</td><td><button class="link-button" *ngIf="event.status==='DEAD'" (click)="replayKafkaDeadLetter(event)">Replay</button><span *ngIf="event.status!=='DEAD'">{{event.status}}</span></td></tr></tbody></table></div></div><p *ngIf="!outboxDiagnostics" class="empty">Loading delivery diagnostics…</p></div></section><section *ngIf="tab==='users'"><div class="panel table-panel"><table><thead><tr><th>CUSTOMER</th><th>ROLE</th><th>VERIFIED</th><th>STATUS</th><th>ACTION</th></tr></thead><tbody><tr *ngFor="let user of users"><td><strong>{{user.firstName}} {{user.lastName}}</strong><small>{{user.email}}</small></td><td>{{user.role}}</td><td>{{user.emailVerified?'Yes':'No'}}</td><td>{{user.active?'Active':'Disabled'}}</td><td><button class="link-button" (click)="setUserActive(user)">{{user.active?'Disable':'Enable'}}</button><button class="link-button" *ngIf="!user.emailVerified" (click)="verifyUser(user)">Verify email</button><button class="link-button" (click)="viewLoyalty(user)">Loyalty</button></td></tr></tbody></table></div><div *ngIf="selectedLoyalty" class="panel"><div class="panel-heading"><div><p class="eyebrow">LOYALTY ACCOUNT</p><h2>{{selectedLoyalty.user.firstName}} {{selectedLoyalty.user.lastName}}</h2></div><button class="link-button" (click)="selectedLoyalty=null">Close</button></div><p>{{selectedLoyalty.account.balance.points}} points · {{selectedLoyalty.account.balance.tier}}</p><button class="primary" (click)="adjustLoyalty()">Adjust points</button><div class="row" *ngFor="let transaction of selectedLoyalty.account.transactions"><span>{{transaction.kind}} · {{transaction.orderId||transaction.refundId||'manual'}}</span><b>{{transaction.points}}</b></div></div></section><p class="error" *ngIf="error">{{error}}</p></main></div>`})
export class AdminComponent {
 distributionPlugins:any[]=[];
 systemSettings:any={storeName:"Artio Store",countryCode:"CH",currencyCode:"CHF",locale:"de-CH",timezone:"Europe/Zurich",externalBaseUrl:"",distributionId:"switzerland-v1"};systemLanguages="de,fr,it,en";systemSettingsAudit:any[]=[];outboxDiagnostics:any=null;outboxDeadEvents:any[]=[];kafkaDeadLetters:any={dead:0,replayPending:0,replayed:0};kafkaDeadLetterItems:any[]=[];kafkaConsumerLag:any=null;setupChecked=false;setupRequired=false;developerMode=false;setupBusy=false;setupToken='';setupPassword='';setupDraft:any={storeName:'Artio Store',countryCode:'CH',currencyCode:'CHF',locale:'de-CH',timezone:'Europe/Zurich',availableLanguages:'de,fr,it,en',externalBaseUrl:'',email:'',firstName:'',lastName:''};
 bundleTranslationBundle:any=null;bundleTranslationLocale='de';bundleTranslationDraft:any={name:'',optionGroupNames:{}};
 private http=inject(HttpClient); token=localStorage.getItem('artio-admin-token'); email=localStorage.getItem('artio-admin-email')??'';password='';error='';extensionHealth='';searchIndexStatus='';tab='overview';query='';products:Product[]=[];bundles:any[]=[];extensions:any[]=[];extensionAudit:any[]=[];extensionAuditFor:string|null=null;extensionInvocation={extensionPoint:'',operation:'health',payloadJson:'{}'};extensionInvocationResult:any=null;selectedExtension:any=null;extensionConfig:Record<string,any>={};extensionManifestJson='';prices:any[]=[];taxRules:any[]=[];sellableTaxCategories:any[]=[];taxAssignment={sellableId:'',category:'STANDARD'};orders:any[]=[];orderPage=0;orderSize=25;orderTotal=0;orderPages=0;ordersQuery='';ordersStatus='';orderStatuses=['PENDING','CONFIRMED','PAID','SHIPPED','DELIVERED','CANCELLED','RETURNED'];selectedOrder:any=null;selectedReturns:any[]=[];selectedTimeline:any[]=[];orderNote='';selectedLoyalty:any=null;users:any[]=[];showCreate=false;showBundle=false;showExtensionRegistration=false;showPrice=false;translationProduct:Product|null=null;translationLocale='de';translationDraft={name:'',description:''};draft={name:'',sku:'',description:''};bundleDraft:any={name:'',sku:'',type:'CONFIGURABLE',sellables:''};priceDraft:any={sellableId:'',amount:0,currency:'USD',market:'US',channel:'WEB',pricesIncludeTax:false};
 get isSuperadmin():boolean{try{const payload=JSON.parse(atob((this.token??"").split(".")[1].replace(/-/g,"+").replace(/_/g,"/")));return payload.role==="SUPERADMIN"}catch{return false}} get title():string{return ({system:"System Settings",overview:'Overview',products:'Products',bundles:'Bundles',extensions:'Extensions',pricing:'Pricing',inventory:'Inventory',orders:'Orders',users:'Customers',giftCards:'Gift cards',operations:'Operations'} as Record<string,string>)[this.tab]??'Overview'}
 get filteredProducts():Product[]{return this.products.filter(p=>p.name.toLowerCase().includes(this.query.toLowerCase())||p.sku.toLowerCase().includes(this.query.toLowerCase()))}
 extensionFields():Array<{key:string;value:any}>{return Object.entries(this.selectedExtension?.manifest.configuration??{}).map(([key,value])=>({key,value}))}
 constructor(){this.loadSetupStatus();if(this.token){this.loadProducts();this.loadBundles();this.loadOrders();this.loadPrices();}}
 loadSetupStatus():void{this.http.get<any>('/api/v1/setup/status').subscribe({next:r=>{this.setupChecked=true;this.setupRequired=!!r.required;this.developerMode=!!r.developerMode},error:()=>{this.setupChecked=true;this.error='Could not check first-run setup status.'}})}
 saveSetupProgress():void{this.setupBusy=true;const headers={'X-Artio-Setup-Token':this.setupToken};this.http.post<any>('/api/v1/setup/resume',{}, {headers}).subscribe({next:status=>{if(status.draft&&Object.keys(status.draft).length)this.setupDraft={...this.setupDraft,...status.draft};this.http.post<any>('/api/v1/setup/progress',this.setupDraft,{headers}).subscribe({next:()=>this.completeSetup(headers),error:e=>{this.setupBusy=false;this.error=e.error?.detail??'Could not save setup progress.'}})},error:e=>{this.setupBusy=false;this.error=e.error?.detail??'Could not verify setup token.'}})}
 completeSetup(headers:any):void{this.http.post<any>('/api/v1/setup/complete',{password:this.setupPassword},{headers}).subscribe({next:()=>{this.setupRequired=false;this.setupBusy=false;this.setupPassword='';this.setupToken='';this.error='Store setup is complete. Sign in with your new administrator account.';this.email=this.setupDraft.email},error:e=>{this.setupBusy=false;this.error=e.error?.detail??'Could not complete store setup.'}})}
 login():void{this.http.post<any>('/api/v1/auth/login',{email:this.email,password:this.password}).subscribe({next:r=>{if(r.role==='CUSTOMER'){this.error='Administrator access is required.';return;}this.token=r.accessToken;localStorage.setItem('artio-admin-token',r.accessToken);localStorage.setItem('artio-admin-email',this.email);this.loadProducts();},error:()=>this.error='Unable to sign in. Check your credentials and administrator role.'})}
 logout():void{localStorage.removeItem('artio-admin-token');localStorage.removeItem('artio-admin-email');this.token=null}
 loadProducts():void{this.http.get<Product[]>('/api/v1/products').subscribe({next:r=>{this.products=r;for(const p of this.products)this.http.get<Array<{id:string;name:string}>>(`/api/v1/products/${p.id}/variants`).subscribe({next:v=>p.variants=v,error:()=>p.variants=[]})},error:()=>this.error='Could not load products.'})}
 loadBundles():void{this.http.get<any[]>('/api/v1/bundles').subscribe({next:r=>this.bundles=r,error:()=>undefined})}
 loadExtensions():void{this.http.get<any[]>('/api/v1/admin/extensions').subscribe({next:r=>this.extensions=r,error:e=>this.error=e.error?.detail??'Could not load extensions.'})}
 invokeExtension():void{if(!this.selectedExtension)return;let payload:any;try{payload=JSON.parse(this.extensionInvocation.payloadJson)}catch{this.error='Diagnostic payload must be valid JSON.';return}const body={...this.extensionInvocation,payload,idempotencyKey:crypto.randomUUID(),deadlineMillis:5000};this.http.post<any>('/api/v1/admin/extensions/'+this.selectedExtension.manifest.id+'/invoke',body).subscribe({next:r=>{this.extensionInvocationResult=r;this.error=''},error:e=>{this.extensionInvocationResult=null;this.error=e.error?.detail??e.error?.message??'Extension diagnostic request failed.'}})}
 loadExtensionAudit(extension:any):void{this.extensionAuditFor=extension.id;this.http.get<any[]>('/api/v1/admin/extensions/'+extension.id+'/audit').subscribe({next:r=>this.extensionAudit=r,error:e=>{this.extensionAudit=[];this.error=e.error?.detail??'Could not load extension activity.'}})}
 rebuildSearchIndex():void{this.searchIndexStatus='Rebuilding search documents…';this.http.post<{productsIndexed:number;translationsIndexed:number}>('/api/v1/admin/catalog/search-index/rebuild',{}).subscribe({next:r=>this.searchIndexStatus=`Indexed ${r.productsIndexed} products and ${r.translationsIndexed} translations.`,error:e=>this.searchIndexStatus=e.error?.detail??'Search index rebuild failed.'})}
 loadPrices():void{this.http.get<any[]>('/api/v1/prices').subscribe({next:r=>this.prices=r,error:()=>undefined});this.http.get<any[]>('/api/v1/tax-rules').subscribe({next:r=>this.taxRules=r,error:()=>undefined});this.http.get<any[]>('/api/v1/tax-rules/sellables/categories').subscribe({next:r=>this.sellableTaxCategories=r,error:()=>undefined})}
 loadOrders(page=this.orderPage):void{this.orderPage=page;const params=new URLSearchParams({page:String(page),size:String(this.orderSize),sort:'createdAt',direction:'desc'});if(this.ordersStatus)params.set('status',this.ordersStatus);if(this.ordersQuery.trim())params.set('q',this.ordersQuery.trim());this.http.get<any>('/api/v1/admin/orders?'+params.toString()).subscribe({next:r=>{this.orders=r.items;this.orderTotal=r.totalElements;this.orderPages=r.totalPages},error:e=>this.error=e.error?.detail??'Could not load orders.'})}
 searchOrders():void{this.loadOrders(0)}
 viewOrder(order:any):void{this.http.get<any>('/api/v1/admin/orders/'+order.id).subscribe({next:r=>{this.selectedOrder=r;this.http.get<any[]>('/api/v1/admin/orders/'+order.id+'/returns').subscribe({next:returns=>this.selectedReturns=returns,error:e=>this.error=e.error?.detail??'Could not load order returns.'});this.loadOrderTimeline(order.id)},error:e=>this.error=e.error?.detail??'Could not load order details.'})}
 loadOrderTimeline(orderId:string):void{this.http.get<any[]>('/api/v1/admin/orders/'+orderId+'/timeline').subscribe({next:events=>this.selectedTimeline=events,error:e=>this.error=e.error?.detail??'Could not load order timeline.'})}
 addOrderNote():void{if(!this.selectedOrder||!this.orderNote.trim())return;this.http.post<any>(`/api/v1/admin/orders/${this.selectedOrder.id}/notes`,{message:this.orderNote.trim()}).subscribe({next:()=>{this.orderNote='';this.loadOrderTimeline(this.selectedOrder.id)},error:e=>this.error=e.error?.detail??'Could not add staff note.'})}
 reviewReturn(item:any,approve:boolean):void{const note=prompt(approve?'Optional approval note':'Reason for rejecting this return');if(note===null)return;this.http.post<any>(`/api/v1/admin/orders/${item.orderId}/returns/${item.id}/review`,{approve,note}).subscribe({next:()=>this.viewOrder({id:item.orderId}),error:e=>this.error=e.error?.detail??'Could not review return.'})}
 receiveReturn(item:any):void{const restock=window.confirm('Restock returned items? Choose Cancel to complete receipt without restocking.');let warehouseId:string|null=null;if(restock){warehouseId=prompt('Warehouse UUID to receive returned stock');if(!warehouseId)return}const note=prompt('Optional receiving note');if(note===null)return;this.http.post<any>(`/api/v1/admin/orders/${item.orderId}/returns/${item.id}/receive`,{restock,warehouseId,note}).subscribe({next:()=>this.viewOrder({id:item.orderId}),error:e=>this.error=e.error?.detail??'Could not receive return.'})}
 refundPayment(payment:any):void{const amount=prompt('Refund amount in '+payment.currency+'. Leave empty to refund the remaining amount.');if(amount===null)return;const normalized=amount.trim();const numeric=normalized?Number(normalized):null;if(numeric!==null&&(!Number.isFinite(numeric)||numeric<=0)){this.error='Enter a positive refund amount.';return}const summary=numeric===null?'the remaining balance':numeric+' '+payment.currency;if(!window.confirm('Confirm refund of '+summary+'? This sends a real refund request to the payment provider.'))return;const storageKey='artio-refund-key:'+payment.id+':'+(normalized||'remaining');let idempotencyKey=sessionStorage.getItem(storageKey);if(!idempotencyKey){idempotencyKey=crypto.randomUUID();sessionStorage.setItem(storageKey,idempotencyKey)}const body={amount:numeric};this.http.post<any>('/api/v1/payments/'+payment.id+'/refund',body,{headers:{'Idempotency-Key':idempotencyKey}}).subscribe({next:()=>{sessionStorage.removeItem(storageKey);if(this.selectedOrder)this.viewOrder({id:this.selectedOrder.id})},error:e=>this.error=e.error?.detail??'Refund was not confirmed. Retry with the same amount.'})}
 exportOrders():void{const params=new URLSearchParams();if(this.ordersStatus)params.set('status',this.ordersStatus);if(this.ordersQuery.trim())params.set('q',this.ordersQuery.trim());this.http.get('/api/v1/admin/orders/export.csv?'+params.toString(),{responseType:'blob'}).subscribe({next:blob=>{const url=URL.createObjectURL(blob);const link=document.createElement('a');link.href=url;link.download='artio-orders.csv';link.click();URL.revokeObjectURL(url)},error:e=>this.error=e.error?.detail??'Could not export orders.'})}
 loadOutbox():void{this.http.get<any>('/api/v1/admin/operations/outbox').subscribe({next:r=>this.outboxDiagnostics=r,error:e=>this.error=e.error?.detail??'Could not load delivery diagnostics.'});this.http.get<any[]>('/api/v1/admin/operations/outbox/events/dead').subscribe({next:r=>this.outboxDeadEvents=r,error:e=>this.error=e.error?.detail??'Could not load dead-letter events.'});this.loadKafkaOperations()}
 loadKafkaOperations():void{this.http.get<any>('/api/v1/admin/operations/kafka/dead-letters').subscribe({next:r=>this.kafkaDeadLetters=r,error:()=>undefined});this.http.get<any[]>('/api/v1/admin/operations/kafka/dead-letters/items').subscribe({next:r=>this.kafkaDeadLetterItems=r,error:()=>undefined});this.http.get<any>('/api/v1/admin/operations/kafka/consumer-lag').subscribe({next:r=>this.kafkaConsumerLag=r,error:()=>this.kafkaConsumerLag=null})}
 replayKafkaDeadLetter(event:any):void{if(!window.confirm('Replay Kafka event '+(event.eventId??event.id)+'? Consumer inbox deduplicates stable event IDs.'))return;this.http.post('/api/v1/admin/operations/kafka/dead-letters/'+event.id+'/replay',{}).subscribe({next:()=>this.loadKafkaOperations(),error:e=>this.error=e.error?.detail??'Could not replay this Kafka event.'})}
 replayOutboxEvent(event:any):void{if(!window.confirm('Replay event '+event.id+'? Consumers must deduplicate this stable event ID.'))return;this.http.post('/api/v1/admin/operations/outbox/events/'+event.id+'/replay',{}).subscribe({next:()=>this.loadOutbox(),error:e=>this.error=e.error?.detail??'Could not replay this event.'})}
 loadSystemSettings():void{this.http.get<any>('/api/v1/admin/system/settings').subscribe({next:r=>{this.systemSettings=r;this.systemLanguages=(r.availableLanguages??[]).join(',')},error:e=>this.error=e.error?.detail??'Could not load system settings.'});this.http.get<any[]>('/api/v1/admin/system/settings/audit').subscribe({next:r=>this.systemSettingsAudit=r,error:e=>this.error=e.error?.detail??'Could not load system settings audit.'});this.loadDistributionPlugins()}
 loadDistributionPlugins():void{this.http.get<any[]>('/api/v1/admin/system/distribution/plugins').subscribe({next:r=>this.distributionPlugins=r,error:e=>this.error=e.error?.detail??'Could not load regional plugin status.'})}
 refreshDistributionPlugins():void{this.http.post<any[]>('/api/v1/admin/system/distribution/plugins/refresh',{}).subscribe({next:r=>this.distributionPlugins=r,error:e=>this.error=e.error?.detail??'Could not refresh regional plugin status.'})}
 saveSystemSettings():void{const request={...this.systemSettings,availableLanguages:this.systemLanguages.split(',').map((v:string)=>v.trim()).filter(Boolean)};this.http.put<any>('/api/v1/admin/system/settings',request).subscribe({next:r=>{this.systemSettings=r;this.systemLanguages=r.availableLanguages.join(',');this.error='';this.loadSystemSettings()},error:e=>this.error=e.error?.detail??'Could not save system settings.'})}
 loadUsers():void{this.http.get<any[]>('/api/v1/admin/users').subscribe({next:r=>this.users=r,error:e=>this.error=e.error?.detail??'Could not load customers.'})}
 shipOrder(order:any):void{const trackingNumber=order.shippingMethodId?null:prompt('Tracking number');if(!order.shippingMethodId&&!trackingNumber)return;this.http.post(`/api/v1/admin/orders/${order.id}/ship`,{trackingNumber}).subscribe({next:()=>this.loadOrders(),error:e=>this.error=e.error?.detail??'Could not ship this order.'})}
 openShippingLabel(order:any):void{const popup=window.open('about:blank','_blank');if(!popup){this.error='Allow pop-ups to open the shipping label.';return}popup.opener=null;this.http.get(`/api/v1/admin/orders/${order.id}/label`,{responseType:'blob'}).subscribe({next:blob=>{const url=URL.createObjectURL(blob);popup.location.href=url;setTimeout(()=>URL.revokeObjectURL(url),60_000)},error:e=>{popup.close();this.error=e.error?.detail??'Could not load the shipping label.'}})}
 deliverOrder(order:any):void{this.http.post(`/api/v1/admin/orders/${order.id}/deliver`,{}).subscribe({next:()=>this.loadOrders(),error:e=>this.error=e.error?.detail??'Could not update this order.'})}
 refreshOrderTracking(order:any):void{this.http.post<any>(`/api/v1/admin/orders/${order.id}/tracking/refresh`,{}).subscribe({next:r=>{this.error='Carrier update: '+r.status+(r.lastLocation?' · '+r.lastLocation:'');this.loadOrders();if(this.selectedOrder?.id===order.id)this.viewOrder(order)},error:e=>this.error=e.error?.detail??'Carrier tracking is not available for this shipping provider.'})}
 setUserActive(user:any):void{this.http.put('/api/v1/admin/users/'+user.id+'/active',{active:!user.active}).subscribe(()=>this.loadUsers())}
 verifyUser(user:any):void{this.http.put('/api/v1/admin/users/'+user.id+'/email-verification',{verified:true}).subscribe(()=>this.loadUsers())}
 viewLoyalty(user:any):void{this.http.get<any>(`/api/v1/admin/loyalty/${user.id}`).subscribe({next:account=>this.selectedLoyalty={user,account},error:e=>this.error=e.error?.detail??'Could not load loyalty account.'})}
 adjustLoyalty():void{if(!this.selectedLoyalty)return;const points=Number(prompt('Points adjustment. Use a negative number to remove points.'));if(!Number.isInteger(points)||points===0||Math.abs(points)>1000000){this.error='Enter a whole point adjustment between -1,000,000 and 1,000,000.';return}const reason=prompt('Reason for this audited adjustment');if(!reason?.trim())return;if(!window.confirm(`Apply ${points>0?'+':''}${points} points?`))return;const user=this.selectedLoyalty.user;const storageKey=`artio-loyalty-adjust:${user.id}:${points}`;let key=sessionStorage.getItem(storageKey);if(!key){key=crypto.randomUUID();sessionStorage.setItem(storageKey,key)}this.http.post<any>(`/api/v1/admin/loyalty/${user.id}/adjust`,{points,reason:reason.trim()},{headers:{'Idempotency-Key':key}}).subscribe({next:account=>{sessionStorage.removeItem(storageKey);this.selectedLoyalty={user,account}},error:e=>this.error=e.error?.detail??'Could not adjust loyalty points.'})}
 createProduct():void{this.http.post<Product>('/api/v1/products',this.draft).subscribe({next:p=>this.http.post(`/api/v1/products/${p.id}/variants`,{name:'Standard',sku:`${this.draft.sku}-STD`}).subscribe({next:()=>{this.showCreate=false;this.draft={name:'',sku:'',description:''};this.loadProducts()},error:e=>this.error=e.error?.detail??'Product created, but its default variant could not be added.'}),error:e=>this.error=e.error?.detail??'Could not create product.'})}
 toggle(p:Product):void{this.http.put(`/api/v1/products/${p.id}/active`,{active:!p.active}).subscribe(()=>this.loadProducts())}
 editTranslations(product:Product):void{this.translationProduct=product;this.translationLocale='de';this.loadTranslation()}
 loadTranslation():void{if(!this.translationProduct)return;this.translationDraft={name:'',description:''};this.http.get<Array<{locale:string;name:string;description:string}>>(`/api/v1/products/${this.translationProduct.id}/translations`).subscribe({next:items=>{const found=items.find(item=>item.locale===this.translationLocale);if(found)this.translationDraft={name:found.name,description:found.description}},error:()=>this.error='Could not load product translations.'})}
 saveTranslation():void{if(!this.translationProduct)return;this.http.put(`/api/v1/products/${this.translationProduct.id}/translations/${this.translationLocale}`,this.translationDraft).subscribe({next:()=>this.error='',error:e=>this.error=e.error?.detail??'Could not save product translation.'})}
 registerExtension():void{try{const manifest=JSON.parse(this.extensionManifestJson);this.http.post('/api/v1/admin/extensions/register',manifest).subscribe({next:()=>{this.showExtensionRegistration=false;this.extensionManifestJson='';this.error='';this.loadExtensions()},error:e=>this.error=e.error?.detail??'Manifest validation or registration failed.'})}catch{this.error='Extension manifest must be valid JSON.'}}
 selectExtension(extension:any):void{this.http.get<any>(`/api/v1/admin/extensions/${extension.id}`).subscribe({next:plugin=>{this.selectedExtension=plugin;this.extensionConfig={...plugin.configuration};for(const key of Object.keys(plugin.manifest.configuration??{})){if(plugin.manifest.configuration[key].type==='secret')this.extensionConfig[key]=''}},error:e=>this.error=e.error?.detail??'Could not load extension settings.'})}
 saveExtensionConfiguration():void{if(!this.selectedExtension)return;const payload={...this.extensionConfig};for(const key of this.selectedExtension.configuredSecrets){if(!payload[key])delete payload[key]}this.http.put(`/api/v1/admin/extensions/${this.selectedExtension.manifest.id}/configuration`,payload).subscribe({next:()=>{this.error='';this.selectedExtension=null;this.loadExtensions()},error:e=>this.error=e.error?.detail??'Extension configuration is invalid.'})}
 openObservability():void{const popup=window.open('about:blank','_blank');if(!popup){this.error='Allow pop-ups to open observability dashboards.';return}popup.opener=null;this.http.get('/api/v1/admin/extensions/observability.artio/ui-session').subscribe({next:()=>{popup.location.href='/plugins/observability/'},error:e=>{popup.close();this.error=e.error?.detail??'Could not open observability dashboards.'}})}
 extensionAction(extension:any,action:'install'|'enable'|'disable'):void{this.http.post(`/api/v1/admin/extensions/${extension.id}/${action}`,{}).subscribe({next:()=>{this.error='';this.extensionHealth='';this.loadExtensions()},error:e=>this.error=e.error?.detail??e.error?.message??`Could not ${action} extension.`})}
 updateExtension(extension:any):void{const manifestJson=window.prompt(`Paste the next manifest JSON for ${extension.id}`);if(!manifestJson)return;try{const manifest=JSON.parse(manifestJson);this.http.post(`/api/v1/admin/extensions/${extension.id}/update`,manifest).subscribe({next:()=>{this.error='';this.loadExtensions()},error:e=>this.error=e.error?.detail??e.error?.message??'Could not update extension.'})}catch{this.error='Manifest must be valid JSON.'}}
 rollbackExtension(extension:any):void{if(!window.confirm(`Roll back ${extension.id} to its previous release?`))return;this.http.post(`/api/v1/admin/extensions/${extension.id}/rollback`,{}).subscribe({next:()=>{this.error='';this.loadExtensions()},error:e=>this.error=e.error?.detail??e.error?.message??'Could not roll back extension.'})} uninstallExtension(extension:any):void{if(!window.confirm(`Remove ${extension.name}? This stops and removes its managed container and purges stored configuration.`))return;this.http.delete(`/api/v1/admin/extensions/${extension.id}`).subscribe({next:()=>{this.error='';this.loadExtensions()},error:e=>this.error=e.error?.detail??e.error?.message??'Could not uninstall extension.'})} rotateExtensionCredentials(extension:any):void{this.http.post(`/api/v1/admin/extensions/${extension.id}/credentials/rotate`,{}).subscribe({next:()=>{this.error='';this.extensionHealth=`${extension.id}: credential rotated`;this.loadExtensions()},error:e=>this.error=e.error?.detail??e.error?.message??'Could not rotate extension credential.'})}
 checkExtensionHealth(extension:any):void{this.http.get<any>(`/api/v1/admin/extensions/${extension.id}/health`).subscribe({next:r=>{this.extensionHealth=`${extension.id}: ${r.healthy?'healthy':r.status}`;this.error=''},error:e=>this.error=e.error?.detail??'Could not read extension health.'})}
 createBundle():void{const ids=String(this.bundleDraft.sellables).split(',').map((x:string)=>x.trim()).filter(Boolean);const body=this.bundleDraft.type==='FIXED'?{name:this.bundleDraft.name,sku:this.bundleDraft.sku,type:'FIXED',pricingRule:{mode:'COMPONENT_SUM'},components:ids.map((sellableId:string)=>({sellableId,quantity:1})),optionGroups:[]}:{name:this.bundleDraft.name,sku:this.bundleDraft.sku,type:'CONFIGURABLE',pricingRule:{mode:'COMPONENT_SUM'},components:[],optionGroups:[{code:'choices',name:'Choose your items',minimumSelections:1,maximumSelections:ids.length,choices:ids.map((sellableId:string)=>({sellableId,quantity:1}))}]};this.http.post('/api/v1/bundles',body).subscribe({next:()=>{this.showBundle=false;this.loadBundles()},error:e=>this.error=e.error?.detail??'Could not create bundle.'})}
 editBundleTranslation(bundle:any):void{this.bundleTranslationBundle=bundle;this.bundleTranslationLocale='de';this.loadBundleTranslation()}
 loadBundleTranslation():void{if(!this.bundleTranslationBundle)return;this.bundleTranslationDraft={name:'',optionGroupNames:{}};this.http.get<any>(`/api/v1/bundles/${this.bundleTranslationBundle.id}/translations/${this.bundleTranslationLocale}`).subscribe({next:r=>this.bundleTranslationDraft={name:r.name??'',optionGroupNames:{...(r.optionGroupNames??{})}},error:e=>this.error=e.error?.detail??'Could not load bundle translations.'})}
 saveBundleTranslation():void{if(!this.bundleTranslationBundle)return;this.http.put(`/api/v1/bundles/${this.bundleTranslationBundle.id}/translations/${this.bundleTranslationLocale}`,this.bundleTranslationDraft).subscribe({next:()=>this.error='',error:e=>this.error=e.error?.detail??'Could not save bundle translations.'})} activateBundle(b:any):void{this.http.put(`/api/v1/bundles/${b.id}/active`,{active:!b.active}).subscribe(()=>this.loadBundles())}
 createPrice():void{this.http.post('/api/v1/prices',{...this.priceDraft,sellableId:this.priceDraft.sellableId,amount:Number(this.priceDraft.amount)}).subscribe({next:()=>{this.showPrice=false;this.loadPrices()},error:e=>this.error=e.error?.detail??'Could not create price.'})}
 assignTaxCategory():void{this.http.put(`/api/v1/tax-rules/sellables/${this.taxAssignment.sellableId}/category`,{category:this.taxAssignment.category}).subscribe({next:()=>{this.error='';this.taxAssignment={sellableId:'',category:'STANDARD'};this.loadPrices()},error:e=>this.error=e.error?.detail??'Could not assign tax category.'})}
}
